  1	package hotel.reservations;
  2	
  3	import hotel.rooms.Room;
  4	import hotel.rooms.RoomType;
  5	import java.math.BigDecimal;
  6	import java.math.RoundingMode;
  7	import java.time.DayOfWeek;
  8	import java.time.LocalDate;
  9	import java.time.Month;
 10	import java.util.Map;
 11	
 12	/**
 13	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
 14	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
 15	 * (half-even) at every step.
 16	 */
 17	public final class PriceCalculator {
 18	
 19	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
 20	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
 21	    static final BigDecimal LONG_STAY_DISCOUNT = new BigDecimal("0.10");
 22	
 23	    static final Map<String, BigDecimal> CORPORATE_DISCOUNTS = Map.of(
 24	            "TECNOSUL", new BigDecimal("0.12"),
 25	            "AGROVALE", new BigDecimal("0.18"),
 26	            "FARMAVIDA", new BigDecimal("0.25"));
 27	
 28	    static final Map<RoomType, BigDecimal> WEEKEND_PACKAGE_PRICES = Map.of(
 29	            RoomType.STANDARD, new BigDecimal("520.00"),
 30	            RoomType.DELUXE, new BigDecimal("820.00"),
 31	            RoomType.SUITE, new BigDecimal("1200.00"));
 32	
 33	    public Price calculate(
 34	            Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan, String companyCode) {
 35	        return switch (ratePlan) {
 36	            case WEEKEND_PACKAGE -> calculateWeekendPackage(room, checkIn, checkOut);
 37	            case CORPORATE -> calculateCorporate(room, checkIn, checkOut, companyCode);
 38	            case LONG_STAY -> calculateLongStay(room, checkIn, checkOut);
 39	            default -> calculateStandardOrNonRefundable(room, checkIn, checkOut, ratePlan);
 40	        };
 41	    }
 42	
 43	    private Price calculateStandardOrNonRefundable(
 44	            Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
 45	        int nights = 0;
 46	        BigDecimal subtotal = cents(BigDecimal.ZERO);
 47	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
 48	            subtotal = subtotal.add(nightPrice(room, night));
 49	            nights++;
 50	        }
 51	        BigDecimal discount = switch (ratePlan) {
 52	            case STANDARD -> cents(BigDecimal.ZERO);
 53	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
 54	            default -> cents(BigDecimal.ZERO);
 55	        };
 56	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
 57	    }
 58	
 59	    private Price calculateCorporate(Room room, LocalDate checkIn, LocalDate checkOut, String companyCode) {
